from hran_radio.radio_classes.radio_5_1_dual_NAHKA_dualband import Radio5_1DualNAHKADualBand
from hran_radio.radio_output_parser.five_one_parser import RadioOutputParser


class Radio5_1DualNAHKADualBand8T8R(Radio5_1DualNAHKADualBand):
    """
In dictionary self.physical_antenna_map key is path from frmon map and value is physical RM antenna pipe
    """

    def __init__(self, radio_ip, sm_ip, msm_ip):
        super(Radio5_1DualNAHKADualBand8T8R, self).__init__(radio_ip, sm_ip, msm_ip)
        self.parser = RadioOutputParser()
        self.first_nahka_ip = radio_ip
        self.second_nahka_ip = "192.168.101.3"
        self.physical_antenna_map = {
            "ant1": "ant1",
            "ant2": "ant2",
            "ant3": "ant3",
            "ant4": "ant4",
            "ant5": "ant5",
            "ant6": "ant6",
            "ant7": "ant7",
            "ant8": "ant8",
        }

    def _run_map_commands_on_both_nahka(self, map_func, trx):
        """
        Run map commands on both nahka

        :param map_func: function create map
        :param trx: tx or rx str()
        :return: tuple(first_raw_map, second_raw_map)
        """
        _first = self._execute_radio_command(
            map_func(trx, first_ant_num=1, last_ant_num=8), self.first_nahka_ip
        )
        _second = self._execute_radio_command(
            map_func(trx, first_ant_num=1, last_ant_num=8), self.second_nahka_ip
        )
        return _first, _second
